import 'package:flutter/material.dart';
import 'package:flutter_native_splash/flutter_native_splash.dart';

void main() {
  // 1. 위젯 바인딩 초기화 및 스플래시 유지
  WidgetsBinding widgetsBinding = WidgetsFlutterBinding.ensureInitialized();
  FlutterNativeSplash.preserve(widgetsBinding: widgetsBinding);

  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: const SplashHandler(),
    );
  }
}

class SplashHandler extends StatefulWidget {
  const SplashHandler({super.key});

  @override
  State<SplashHandler> createState() => _SplashHandlerState();
}

class _SplashHandlerState extends State<SplashHandler> {
  @override
  void initState() {
    super.initState();
    _initializeApp();
  }

  Future<void> _initializeApp() async {
    // 앱 초기화 작업들
    await Future.wait([
      _loadUserData(),
      _initializeServices(),
      _checkAuthStatus(),
    ]);

    // 최소 2초는 스플래시 표시 (UX를 위해)
    await Future.delayed(const Duration(seconds: 2));

    // 2. 초기화 완료 후 스플래시 제거
    FlutterNativeSplash.remove();
  }

  Future<void> _loadUserData() async {
    // 사용자 데이터 로드
    await Future.delayed(const Duration(milliseconds: 500));
  }

  Future<void> _initializeServices() async {
    // Firebase, Analytics 등 초기화
    await Future.delayed(const Duration(milliseconds: 800));
  }

  Future<void> _checkAuthStatus() async {
    // 로그인 상태 확인
    await Future.delayed(const Duration(milliseconds: 300));
  }

  @override
  Widget build(BuildContext context) {
    return const Scaffold(
      body: Center(
        child: Text('앱 메인 화면'),
      ),
    );
  }
}
